def note_for(filename, code):
    """Busca una nota revisada; las coincidencias Java nunca se aplican a archivos de otro lenguaje."""
    entries = ANDROID if filename.endswith('.java') else NOTES.get(filename, {})
    return entries.get(code.strip())
